const now = new Date();
const todayStr = now.toISOString().split('T')[0];
const dayOfWeek = now.toLocaleDateString('en-US', { weekday: 'long' });

return [{
  json: {
    chatId: $json.message.chat.id,
    userMessage: $json.message.text,
    currentDate: todayStr,
    currentDayOfWeek: dayOfWeek
  }
}];

const responseRaw = $json.response;
let parsed = {};

try {
  // Use Regex to extract only the JSON part from inside the chat/markdown text
  const match = typeof responseRaw === 'string' ? responseRaw.match(/\{[\s\S]*\}/) : null;
  const jsonString = match ? match[0] : responseRaw;

  parsed = typeof jsonString === 'string' ? JSON.parse(jsonString) : jsonString;
} catch(e) {
  parsed = { intent: 'UNKNOWN', raw: responseRaw, error: e.message };
}

// Smart fallback: If the model forgot the 'payload' wrapper, build it manually
let finalPayload = parsed.payload;
if (!finalPayload && parsed.intent === 'WRITE') {
  finalPayload = {
    production_kg: parsed.production_kg || null,
    sales: parsed.sales || {},
    meter_1: parsed.meter_1 || null,
    meter_2: parsed.meter_2 || null
  };
}

return [{
  json: {
    chatId: $('Get Date Context').item.json.chatId,
    originalMessage: $('Get Date Context').item.json.userMessage,
    intent: parsed.intent || 'UNKNOWN',
    target_date: parsed.target_date || $('Get Date Context').item.json.currentDate,
    start_date: parsed.start_date || $('Get Date Context').item.json.currentDate,
    end_date: parsed.end_date || $('Get Date Context').item.json.currentDate,
    payload: finalPayload || {},
    read_query: parsed.read_query || $('Get Date Context').item.json.userMessage
  }
}];
